field.eval:
[
  {
    "type": "start",
    "config": {"variables": [
      {"name": "days", "type": "required", "description": "Only invoices due more than this many days ago"},
      {"name": "limit", "type": "optional", "value": 10, "description": "How many invoices to chase"}
    ]}
  },
  {
    "type": "search",
    "config": {"args": {
      "model": "account.move",
      "domain": [["move_type", "=", "out_invoice"], ["payment_state", "in", ["not_paid", "partial"]]],
      "fields": ["name", "partner_id", "amount_residual", "invoice_date_due"],
      "limit": 10,
      "order": "invoice_date_due asc"
    }},
    "resultVariable": "overdue"
  },
  {
    "type": "agent",
    "config": {"instruction": "Write a short, friendly reminder for each overdue invoice in ${overdue}. One paragraph per invoice, naming the invoice number, the customer and the amount due. Plain text, no subject line, no sign-off."},
    "resultVariable": "drafts"
  },
  {
    "type": "output",
    "config": {"value": "${drafts}"}
  }
]

[
  {
    "type": "start",
    "config": {"variables": [
      {"name": "location", "type": "required", "description": "Location name or id to check"}
    ]}
  },
  {
    "type": "search",
    "config": {"args": {
      "model": "stock.quant",
      "domain": [["quantity", "<=", 0], ["location_id", "ilike", "${location}"]],
      "fields": ["product_id", "location_id", "quantity", "reserved_quantity"],
      "limit": 25
    }},
    "resultVariable": "quants"
  },
  {
    "type": "agent",
    "config": {"instruction": "Report the stock situation from ${quants}. One line per quant: product, location, on hand, reserved, and the action. If there are no reorder points on file, say the shortfall cannot be computed rather than inventing one."},
    "resultVariable": "report"
  },
  {
    "type": "output",
    "config": {"value": "${report}"}
  }
]
